Encode the linear cycle as a successor map and handle start/cancel as guarded transitions; any event not valid in the current state leaves it unchanged.
```python
def washing_machine_state(events: list[str]) -> str:
    following = {
        "filling": "washing",
        "washing": "rinsing",
        "rinsing": "draining",
        "draining": "idle",
    }
    state = "idle"
    for event in events:
        if event == "start" and state == "idle":
            state = "filling"
        elif event == "next" and state in following:
            state = following[state]
        elif event == "cancel" and state in ("filling", "washing", "rinsing"):
            state = "draining"
    return state
```

Dict key views support set operations, so added and removed are key-view differences and changed is the intersection filtered by value inequality.
```python
def describe_dict_changes(old: dict, new: dict) -> dict:
    old_keys, new_keys = old.keys(), new.keys()
    return {
        "added": sorted(new_keys - old_keys),
        "removed": sorted(old_keys - new_keys),
        "changed": sorted(k for k in old_keys & new_keys if old[k] != new[k]),
    }
```

An odometer is a counter modulo 10**digits, so add the distance and reduce modulo that base.
```python
def odometer_reading(start: int, distance: int, digits: int) -> int:
    return (start + distance) % (10 ** digits)
```

Lowercase and split on 'x', requiring exactly two parts; strip each and check it is a positive ASCII integer. Funnel every failure into one ValueError.
```python
def parse_dimension(spec: str) -> tuple[int, int]:
    parts = spec.lower().split("x")
    if len(parts) == 2:
        w, h = (p.strip() for p in parts)
        if all(p.isascii() and p.isdigit() and int(p) > 0 for p in (w, h)):
            return int(w), int(h)
    raise ValueError(f"invalid dimension: {spec!r}")
```

Backtrack over where the next operand ends, carrying the running value; each new operand is either added or subtracted (the first is taken as-is), and operands with a leading zero are cut off immediately.
```python
def plus_minus_expressions(digits: str, target: int) -> list[str]:
    n = len(digits)
    found = []

    def backtrack(i: int, expr: str, value: int) -> None:
        if i == n:
            if value == target:
                found.append(expr)
            return
        for j in range(i + 1, n + 1):
            piece = digits[i:j]
            if len(piece) > 1 and piece[0] == '0':
                break
            num = int(piece)
            if i == 0:
                backtrack(j, piece, num)
            else:
                backtrack(j, expr + '+' + piece, value + num)
                backtrack(j, expr + '-' + piece, value - num)

    if n:
        backtrack(0, '', 0)
    return sorted(found)
```

This is a lower-bound binary search over the half-open range [lo, hi): shrink toward the first position whose value is not less than the target, which naturally yields len(nums) when every element is smaller.
```python
from typing import List


def first_index_not_below(sorted_nums: List[int], target: int) -> int:
    lo, hi = 0, len(sorted_nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if sorted_nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo
```

Sort on the tuple (casefolded name, original name): the casefolded form gives case-insensitive ordering and the original string acts as a deterministic tie-breaker.
```python
from typing import List


def sort_names_ignoring_case(names: List[str]) -> List[str]:
    return sorted(names, key=lambda s: (s.casefold(), s))
```

Maintain a counter bounded to [0, capacity] while processing events and keep a running maximum.
```python
def parking_peak_occupancy(events: list[str], capacity: int) -> int:
    count = peak = 0
    for event in events:
        if event == "in" and count < capacity:
            count += 1
        elif event == "out" and count > 0:
            count -= 1
        peak = max(peak, count)
    return peak
```

Turn each string into a set of lowercase letters, intersect the sets, and join the sorted result.
```python
def shared_letters_sorted(a: str, b: str) -> str:
    letters_a = {ch for ch in a.lower() if ch.isalpha()}
    letters_b = {ch for ch in b.lower() if ch.isalpha()}
    return "".join(sorted(letters_a & letters_b))
```

Use dict.setdefault to create each bucket on first sight and append words to it, skipping empty strings.
```python
def group_words_by_initial(words: list) -> dict:
    groups = {}
    for word in words:
        if word:
            groups.setdefault(word[0].lower(), []).append(word)
    return groups
```

Use the generalized Euler theorem a^e = a^(e mod phi(m) + phi(m)) (mod m), valid for e >= phi(m) even when gcd(a, m) > 1, and recurse up the tower with modulus phi(m), which falls to 1 in O(log m) steps. A separate capped evaluation decides whether the exponent is actually below phi(m), in which case it is used exactly.
```python
def power_tower_mod(bases: list[int], m: int) -> int:
    def totient(n: int) -> int:
        result, p = n, 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    def capped(i: int, cap: int) -> int:
        """min(tower from index i, cap), for cap >= 1."""
        if i == len(bases):
            return min(1, cap)
        a = bases[i]
        if a == 1:
            return 1
        exponent = capped(i + 1, cap)
        value = 1
        for _ in range(exponent):
            value *= a
            if value >= cap:
                return cap
        return value

    def solve(i: int, mod: int) -> int:
        if mod == 1:
            return 0
        if i == len(bases):
            return 1
        phi = totient(mod)
        exponent = capped(i + 1, phi)
        if exponent >= phi:
            exponent = solve(i + 1, phi) + phi
        return pow(bases[i], exponent, mod)

    return solve(0, m) % m
```

Map each command to a direction vector and apply it only when the resulting cell stays within bounds.
```python
from typing import Tuple


def clamped_walk_endpoint(moves: str, rows: int, cols: int, start: Tuple[int, int] = (0, 0)) -> Tuple[int, int]:
    deltas = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}
    r, c = start
    for move in moves:
        if move not in deltas:
            continue
        dr, dc = deltas[move]
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            r, c = nr, nc
    return (r, c)
```

Keep a boolean per lamp and flip it for each valid press; the lamps that end up on are those pressed an odd number of times.
```python
def lamps_on_after_presses(n: int, presses: list[int]) -> list[int]:
    on = [False] * n
    for i in presses:
        if 0 <= i < n:
            on[i] = not on[i]
    return [i for i, lit in enumerate(on) if lit]
```

Counting 'exactly k' directly is awkward, but 'at most k' is a simple sliding window that adds the number of valid subarrays ending at each right index; exactly k equals at_most(k) minus at_most(k-1).
```python
def count_subarrays_exactly_k_distinct(nums: list, k: int) -> int:
    def at_most(limit):
        if limit <= 0:
            return 0
        counts = {}
        left = 0
        total = 0
        for right, x in enumerate(nums):
            counts[x] = counts.get(x, 0) + 1
            while len(counts) > limit:
                y = nums[left]
                counts[y] -= 1
                if counts[y] == 0:
                    del counts[y]
                left += 1
            total += right - left + 1
        return total

    return at_most(k) - at_most(k - 1)
```

Try every cell as a starting point and depth-first search for the next letter among the four neighbours, marking cells as used on the way down and unmarking them when backtracking.
```python
def grid_contains_word_path(grid: list[str], word: str) -> bool:
    if not word:
        return True
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    used = set()

    def search(r: int, c: int, i: int) -> bool:
        if grid[r][c] != word[i] or (r, c) in used:
            return False
        if i == len(word) - 1:
            return True
        used.add((r, c))
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and search(nr, nc, i + 1):
                used.discard((r, c))
                return True
        used.discard((r, c))
        return False

    return any(search(r, c, 0) for r in range(rows) for c in range(cols))
```

Fix the right window's end and pair it with the best left window that finishes before it; a running maximum makes that lookup O(1). Do this for both orderings and take the larger, with prefix sums giving each window sum in O(1).
```python
from typing import List


def best_two_disjoint_windows(nums: List[int], first_len: int, second_len: int) -> int:
    prefix = [0]
    for x in nums:
        prefix.append(prefix[-1] + x)

    def window(end: int, length: int) -> int:
        return prefix[end] - prefix[end - length]

    def best_with_left(left_len: int, right_len: int) -> int:
        best_left = float("-inf")
        best = float("-inf")
        for end in range(left_len + right_len, len(nums) + 1):
            best_left = max(best_left, window(end - right_len, left_len))
            best = max(best, best_left + window(end, right_len))
        return best

    return int(max(best_with_left(first_len, second_len), best_with_left(second_len, first_len)))
```

Each cell's route count is the sum of the counts from the cell above and the cell to the left; a single rolling row suffices.
```python
def count_monotone_grid_routes(rows: int, cols: int) -> int:
    if rows <= 0 or cols <= 0:
        return 0
    row = [1] * cols
    for _ in range(1, rows):
        for c in range(1, cols):
            row[c] += row[c - 1]
    return row[-1]
```

Place one rook per row, trying every column that is still free and not forbidden, and backtrack after counting the completions below; this enumerates exactly the valid permutations.
```python
def count_rook_placements_avoiding(n: int, forbidden: set[tuple[int, int]]) -> int:
    used_cols = [False] * n

    def place(row: int) -> int:
        if row == n:
            return 1
        total = 0
        for col in range(n):
            if not used_cols[col] and (row, col) not in forbidden:
                used_cols[col] = True
                total += place(row + 1)
                used_cols[col] = False
        return total

    return place(0)
```

Validate the whole string with a single fullmatch so stray characters are rejected, then findall the (number, unit) pairs and sum number times unit size.
```python
import re


def parse_duration_seconds(spec: str) -> int:
    units = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    if not re.fullmatch(r"(?:[0-9]+[dhmsDHMS])+", spec):
        raise ValueError(f"invalid duration: {spec!r}")
    return sum(int(n) * units[u.lower()] for n, u in re.findall(r"([0-9]+)([A-Za-z])", spec))
```

Keep a boolean that flips only when a letter is emitted, so punctuation and spaces pass through without disturbing the upper/lower rhythm.
```python
def alternate_letter_case(text: str) -> str:
    out = []
    upper = True
    for ch in text:
        if ch.isalpha():
            out.append(ch.upper() if upper else ch.lower())
            upper = not upper
        else:
            out.append(ch)
    return "".join(out)
```

Every parenthesization has some operator applied last; recursively compute the value sets of the operand ranges on each side of each operator and combine them, memoizing by range so shared subexpressions are evaluated once.
```python
import re
from functools import lru_cache


def all_parenthesization_values(expression: str) -> list[int]:
    tokens = re.findall(r'[0-9]+|[-+*]', expression)
    numbers = [int(t) for t in tokens[0::2]]
    operators = tokens[1::2]
    apply = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
    }

    @lru_cache(maxsize=None)
    def values(lo: int, hi: int) -> frozenset:
        if lo == hi:
            return frozenset([numbers[lo]])
        out = set()
        for split in range(lo, hi):
            op = apply[operators[split]]
            for a in values(lo, split):
                for b in values(split + 1, hi):
                    out.add(op(a, b))
        return frozenset(out)

    return sorted(values(0, len(numbers) - 1))
```

Build the answer greedily, trying the smallest allowed character at each position and keeping it only if the rest is still arrangeable. A multiset of size L can follow character `last` exactly when no count exceeds ceil(L/2), and, when L is odd, the character that reaches ceil(L/2) is not `last`.
```python
def smallest_no_adjacent_repeat(text: str) -> str:
    from collections import Counter

    counts = Counter(text)

    def feasible(last, remaining):
        if remaining == 0:
            return True
        limit = (remaining + 1) // 2
        for ch, c in counts.items():
            if c > limit:
                return False
            if remaining % 2 == 1 and c == limit and ch == last:
                return False
        return True

    if not feasible("", len(text)):
        return ""
    out = []
    last = ""
    for remaining in range(len(text), 0, -1):
        for ch in sorted(counts):
            if counts[ch] == 0 or ch == last:
                continue
            counts[ch] -= 1
            if feasible(ch, remaining - 1):
                out.append(ch)
                last = ch
                break
            counts[ch] += 1
    return "".join(out)
```

A negative lookbehind rejects '#' glued to a word or another '#', and the capture group grabs the tag body. A dict used as an ordered set deduplicates the lowercased tags while keeping first-appearance order.
```python
import re


def extract_hashtags(text: str) -> list[str]:
    seen: dict[str, None] = {}
    for tag in re.findall(r"(?<![\w#])#(\w+)", text):
        seen.setdefault(tag.lower(), None)
    return list(seen)
```

Keep a deque of indices whose values are strictly decreasing; smaller values behind a new element can never be a future maximum, so pop them. The front is the current window maximum once expired indices are dropped, and each index enters and leaves once.
```python
from collections import deque
from typing import List


def window_maximums(nums: List[int], k: int) -> List[int]:
    if k < 1 or k > len(nums):
        return []
    candidates: deque = deque()
    result: List[int] = []
    for i, x in enumerate(nums):
        while candidates and nums[candidates[-1]] <= x:
            candidates.pop()
        candidates.append(i)
        if candidates[0] <= i - k:
            candidates.popleft()
        if i >= k - 1:
            result.append(nums[candidates[0]])
    return result
```

Use the product formula phi(n) = n * prod(1 - 1/p) over distinct primes p dividing n, finding those primes by trial division and applying each factor with exact integer arithmetic.
```python
def euler_totient_value(n: int) -> int:
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result
```
